public static int sumPositive(Queue<Integer> q) {
    Queue<Integer> temp = new Queue<Integer>();
    int sum = 0;
    while (!q.isEmpty()) {
        int x = q.remove();
        if (x > 0) sum += x;
        temp.insert(x);
    }
    while (!temp.isEmpty()) q.insert(temp.remove());
    return sum;
}

